<template>
  <div class="idmp-page factor-editor">
  <PageHeader :title="pageTitle"><template #actions><div class="page-toolbar"><el-button :icon="ArrowLeft" @click="router.push('/factor')">返回列表</el-button><el-button type="primary" :loading="loading.save" :disabled="workflow.published" @click="saveFactor">{{ isCreate ? '保存因子定义' : '保存修改' }}</el-button></div></template></PageHeader>
  <el-alert v-if="!isCreate" class="editor-alert" type="info" show-icon :closable="false" :title="workflow.message || '当前页面沿用 0727 版分步配置结构，保存后可继续完成编译、试算和发布。'" />
    <section class="surface-card editor-section"><div class="section-title"><span>1</span><div><h2>基础信息</h2><p>填写因子的编码、名称和业务说明，保存后会生成可继续校验的因子草稿。</p></div></div><el-form ref="basicFormRef" :model="basicForm" :rules="basicRules" label-width="88px"><el-row :gutter="16"><el-col :xs="24" :md="8"><el-form-item label="因子编码" prop="code"><el-input v-model.trim="basicForm.code" :disabled="!isCreate" placeholder="请输入唯一业务编码" /></el-form-item></el-col><el-col :xs="24" :md="8"><el-form-item label="因子名称" prop="name"><el-input v-model.trim="basicForm.name" placeholder="请输入因子名称" /></el-form-item></el-col><el-col :xs="24" :md="8"><el-form-item label="业务分类"><el-input v-model.trim="basicForm.category" placeholder="如：医疗质量" /></el-form-item></el-col></el-row><el-form-item label="说明"><el-input v-model.trim="basicForm.description" type="textarea" :rows="2" placeholder="说明因子的业务含义、统计口径或使用场景" /></el-form-item></el-form><div v-if="workflow.factorId || workflow.versionId" class="saved-summary"><span>因子 ID：<strong>{{ workflow.factorId || '-' }}</strong></span><span>版本 ID：<strong>{{ workflow.versionId || '-' }}</strong></span><span>保存状态：<strong>{{ workflow.status || 'DRAFT' }}</strong></span></div></section>
    <section class="surface-card editor-section caliber-section"><div class="section-title"><span>2</span><div><h2>计算口径配置</h2><p>按业务顺序选择数据来源、计算方式、筛选范围和输出粒度。</p></div></div><div class="caliber-preview"><span>当前口径</span><strong>{{ caliberDescription }}</strong></div><div class="form-block"><div class="block-title"><h3>第一步：从哪里取数？</h3><p>数据域确定业务范围，语义表确定参与计算的数据集合。</p></div><el-form label-position="top"><el-row :gutter="18"><el-col :xs="24" :lg="12"><el-form-item label="数据域"><el-select v-model="dslForm.domainCode" filterable clearable :loading="loading.domains" placeholder="可按中文名称或编码搜索已发布数据域" @change="handleDomainChange"><el-option v-for="domain in domains" :key="domain.code" :label="metadataOptionLabel(domain)" :value="domain.code"><template #default><span>{{ metadataOptionLabel(domain) }}</span><small v-if="domain.description"> · {{ domain.description }}</small></template></el-option></el-select></el-form-item></el-col><el-col :xs="24" :lg="12"><el-form-item label="语义表"><el-select v-model="dslForm.tableCode" filterable clearable :disabled="!dslForm.domainCode" placeholder="请先选择数据域，再按中文名称或编码搜索" @change="handleTableChange"><el-option v-for="table in tables" :key="table.code" :label="metadataOptionLabel(table)" :value="table.code"><template #default><span>{{ metadataOptionLabel(table) }}</span><small v-if="table.sourceTableName"> · 来源：{{ table.sourceTableName }}</small></template></el-option></el-select></el-form-item></el-col></el-row></el-form><div class="time-binding"><div><span>统计周期字段</span><strong>{{ currentTimeFieldLabel }}</strong></div><small>试算周期由语义表默认时间字段自动绑定，不需要在业务筛选中重复配置。</small></div></div></section>
    <section class="surface-card editor-section"><div class="section-title"><span>3</span><div><h2>统计方式</h2><p>统计方式只选一种；分组维度可不选或多选，决定结果按什么粒度输出。</p></div></div><div class="measure-cards"><button v-for="item in aggregationOptions" :key="item.value" type="button" class="measure-card" :class="{active:dslForm.aggregation===item.value}" @click="selectAggregation(item.value)"><strong>{{ item.label }}</strong><span>{{ item.description }}</span></button></div><el-form label-width="88px" class="measure-field"><el-form-item :label="dslForm.aggregation === 'COUNT' ? '计数字段' : '统计字段'"><el-select v-model="dslForm.fieldCode" filterable clearable :placeholder="dslForm.aggregation === 'COUNT' ? '不选为 COUNT(*)；选择字段为 COUNT(字段)' : '选择要聚合的数值/业务键'"><el-option v-for="field in aggregatableFields" :key="field.code" :label="fieldOptionLabel(field)" :value="field.code" /></el-select></el-form-item></el-form><el-form label-width="88px" class="group-by-form"><el-form-item label="分组维度"><el-select v-model="dslForm.groupBy" multiple collapse-tags filterable clearable :disabled="!dslForm.tableCode" placeholder="不选表示统计总体"><el-option v-for="field in dimensionFields" :key="field.code" :label="fieldOptionLabel(field)" :value="field.code" /></el-select></el-form-item></el-form><div class="grain-hint">当前结果粒度：{{ grainDescription }}</div></section>
    <section class="surface-card editor-section"><div class="section-title"><span>4</span><div><h2>筛选范围</h2><p>当前后端仅支持日期字段绑定试算周期；业务值等于、数值比较和值集筛选尚未开放。</p></div></div><el-alert class="filter-capability" type="info" :closable="false" show-icon title="通常选择“全部记录”即可，平台会按语义表默认时间字段应用下方试算周期。只有验证显式 period DSL 时才选择“显式周期条件”。" /><div class="scope-mode"><el-radio-group v-model="scopeMode"><el-radio label="ALL">全部记录（推荐）</el-radio><el-radio label="FILTERED" :disabled="!supportedFilterFields.length">显式周期条件</el-radio></el-radio-group></div><FactorRuleBuilder v-if="scopeMode === 'FILTERED'" :model-value="filters" :fields="supportedFilterFields" @update="ruleVersion++" /><div class="rule-explanation"><strong>口径预览</strong><span>{{ filterPreview }}</span></div><div class="section-footer"><el-button link type="primary" @click="showDsl=true">查看技术配置</el-button></div></section>
    <section v-if="template.templateId" class="surface-card editor-section"><div class="section-title"><span>5</span><div><h2>模板参数</h2><p>模板参数仅作为业务输入，保存时由后端实例化为最终 DSL。</p></div></div><el-form label-position="top"><el-form-item v-for="item in parameters" :key="item.code" :label="item.displayName || item.code"><el-date-picker v-if="String(item.dataType || item.type).includes('DATETIME')" v-model="parameterValues[item.code]" type="datetimerange" value-format="YYYY-MM-DDTHH:mm:ss" /><el-select v-else-if="item.valueSourceType === 'ENUM' || item.valueSourceType === 'VALUE_SET'" v-model="parameterValues[item.code]" filterable><el-option v-for="option in item.options || []" :key="option.value || option.code || option" :label="option.label || option.name || option" :value="option.value || option.code || option" /></el-select><el-input v-else v-model="parameterValues[item.code]" /></el-form-item></el-form></section>
    <section v-if="workflow.versionId" class="surface-card editor-section workflow-section"><div class="section-title"><span>{{ template.templateId ? 6 : 5 }}</span><div><h2>校验、试算与发布</h2><p>因子草稿已保存，请按顺序完成编译校验、试算并查看结果、发布。</p></div><el-tag :type="workflow.published ? 'success' : 'info'">{{ workflow.status || 'DRAFT' }}</el-tag></div><div class="workflow-identity"><div><span>因子 ID</span><strong>{{ workflow.factorId }}</strong></div><div><span>版本 ID</span><strong>{{ workflow.versionId }}</strong></div><div><span>编译产物</span><strong>{{ workflow.artifactId || '-' }}</strong></div><div><span>试算批次</span><strong>{{ workflow.batchId || '-' }}</strong></div></div><el-steps :active="workflowActiveStep" finish-status="success" simple class="workflow-steps"><el-step title="保存草稿" /><el-step title="编译校验" /><el-step title="试算完成" /><el-step title="版本发布" /></el-steps><div class="workflow-actions"><el-button type="primary" :loading="loading.compile" :disabled="workflow.published" @click="compileCurrentVersion">编译并校验</el-button><el-button :loading="loading.trial || loading.result" :disabled="!workflow.compiled || workflow.published" @click="trialCurrentVersion">{{ trialButtonLabel }}</el-button><el-button type="success" :loading="loading.publish" :disabled="!canPublish" @click="publishCurrentVersion">发布因子版本</el-button></div><div v-if="workflow.taskId" class="workflow-feedback"><span>任务 ID：{{ workflow.taskId }}</span><span>任务状态：<el-tag size="small">{{ workflow.taskStatus || 'QUEUED' }}</el-tag></span><el-button v-if="!isTerminalTask" link type="primary" :loading="loading.status" @click="refreshTrialStatus">刷新状态</el-button></div><el-alert v-if="workflow.message" :title="workflow.message" :type="workflow.messageType" :closable="false" show-icon class="workflow-alert" /><div v-if="trialRows.length" class="trial-results"><div class="result-head"><h3>试算结果</h3><span>共 {{ trialRows.length }} 条</span></div><el-table :data="trialRows" size="small" border><el-table-column type="index" label="#" width="54" /><el-table-column label="维度" min-width="220"><template #default="{ row }"><span class="mono-data">{{ formatDimensions(row) }}</span></template></el-table-column><el-table-column label="结果值" min-width="130"><template #default="{ row }">{{ resultValue(row) }}</template></el-table-column><el-table-column label="质量状态" width="120"><template #default="{ row }">{{ row.qualityStatus || workflow.qualityStatus || '-' }}</template></el-table-column></el-table></div><div v-if="workflow.published" class="published-next"><strong>因子版本已发布，可以进入下一步。</strong><span>后续创建指标时，请引用因子版本 ID {{ workflow.versionId }}。</span><el-button type="primary" @click="router.push('/indicator/edit/new')">创建指标</el-button><el-button @click="router.push('/factor')">返回因子目录</el-button></div></section>
    <div v-if="workflow.versionId" class="trial-period trial-period-card"><div><strong>本次试算周期</strong><small>试算时间仅用于本次执行，按半开区间 [开始时间，结束时间) 计算，允许跨年度；由语义表默认时间字段自动绑定。</small></div><el-date-picker v-model="trialPeriod" type="datetimerange" value-format="YYYY-MM-DDTHH:mm:ss" start-placeholder="开始时间" end-placeholder="结束时间" /></div>
    <div class="editor-actions-bar"><span v-if="workflow.message">{{ workflow.message }}</span><span v-else>请完成配置后保存草稿，继续进入编译、试算与发布。</span><el-button :loading="loading.save" :disabled="workflow.published" @click="saveFactor">{{ isCreate ? '保存草稿并继续' : '保存修改并重新校验' }}</el-button></div>
    <DslPreview v-model="showDsl" :dsl="currentDsl" />
  </div>
</template>
<script setup>
import { computed, onMounted, reactive, ref } from 'vue'
import { useRoute, useRouter } from 'vue-router'
import { ElMessage, ElMessageBox } from 'element-plus'
import { ArrowLeft } from '@element-plus/icons-vue'
import PageHeader from '@/idmp/components/PageHeader.vue'
import FactorRuleBuilder from '@/idmp/components/FactorRuleBuilder.vue'
import DslPreview from '@/idmp/components/DslPreview.vue'
import { fetchDataDomains, fetchSemanticTableFields, fetchSemanticTables } from '@/idmp/api/modules/meta'
import { adaptDataDomainList, adaptSemanticFieldList, adaptSemanticTableList } from '@/idmp/api/adapters/meta'
import { compileFactorVersion, createFactor, fetchFactor, fetchFactorTemplateParameterSchema, fetchFactorTrialResults, fetchFactorVersion, fetchFactorVersionsByFactor, instantiateFactorTemplateVersion, publishFactorVersion, trialFactorVersion, updateFactor } from '@/idmp/api/modules/factors'
import { fetchAsyncTask } from '@/idmp/api/modules/calculation'
import { normalizeSemanticField, fieldByCode } from '@/idmp/utils/semanticField'
import { buildFactorDsl, validateFilterNode } from '@/idmp/utils/dslBuilder'
const route=useRoute();const router=useRouter();const basicFormRef=ref();const showDsl=ref(false);const ruleVersion=ref(0);const isCreate=computed(()=>!route.params.id||route.params.id==='new');const pageTitle=computed(()=>isCreate.value?'因子编辑 / 新增因子':`因子编辑 / ${basicForm.name||route.params.id}`)
const basicForm=reactive({code:`FACTOR_${Date.now()}`,name:'',description:'',category:''});const dslForm=reactive({domainCode:'',tableCode:'',aggregation:'COUNT',fieldCode:'',groupBy:[]});const filters=reactive({nodeType:'AND',children:[]});const scopeMode=ref('ALL');const template=reactive({templateId:route.query.templateId||'',versionId:route.query.versionId||''});const parameters=ref([]);const parameterValues=reactive({});const domains=ref([]);const tables=ref([]);const fields=ref([]);const metadataRequestVersion=ref(0);const resourceVersion=ref(0);const loading=reactive({domains:false,template:false,save:false,compile:false,trial:false,result:false,publish:false,status:false});const trialPeriod=ref(['2026-03-01T00:00:00','2026-04-01T00:00:00']);const trialRows=ref([]);const workflow=reactive({factorId:'',versionId:'',status:'',artifactId:'',compiled:false,taskId:'',batchId:'',taskStatus:'',qualityStatus:'',resultsLoaded:false,published:false,message:'',messageType:'info'});
const aggregationOptions=[{value:'COUNT',label:'记录计数',description:'统计符合条件的记录行数（COUNT(*)）'},{value:'COUNT_DISTINCT',label:'去重计数',description:'按患者、就诊或其他业务键去重计数'},{value:'SUM',label:'数值求和',description:'汇总金额、数量、天数等数值字段'},{value:'AVG',label:'平均值',description:'计算数值字段的平均值'},{value:'MIN',label:'最小值',description:'取数值或时间字段的最小值'},{value:'MAX',label:'最大值',description:'取数值或时间字段的最大值'}];const basicRules={code:[{required:true,message:'请输入因子编码',trigger:'blur'}],name:[{required:true,message:'请输入因子名称',trigger:'blur'}]};const currentDomainName=computed(()=>domains.value.find(x=>x.code===dslForm.domainCode)?.name||'未选择数据域');const currentTableName=computed(()=>tables.value.find(x=>x.code===dslForm.tableCode)?.name||dslForm.tableCode);const aggregatableFields=computed(()=>fields.value.filter(field=>{if(field.aggregatable===false)return false;if(dslForm.aggregation==='COUNT_DISTINCT')return true;return ['SUM','AVG'].includes(dslForm.aggregation)?field.kind==='NUMBER':['MIN','MAX'].includes(dslForm.aggregation)?['NUMBER','DATETIME'].includes(field.kind):true}));const dimensionFields=computed(()=>fields.value.filter(field=>field.groupable !== false && ['CODE','STRING','VALUE_SET'].includes(field.kind)));const filterFields=computed(()=>fields.value.filter(field=>field.filterable !== false));const grainDescription=computed(()=>dslForm.groupBy.length?dslForm.groupBy.map(code=>fieldByCode(fields.value,code)?.label||code).join(' × '):'总体（不分组）');const currentDsl=computed(()=>buildDsl());const ruleExplanation=computed(()=>{ruleVersion.value;if(scopeMode.value==='ALL')return '统计当前语义表中的全部记录（DSL filters = TRUE）';if(!filters.children?.length)return '尚未添加筛选条件';if(validateFilterNode(filters).length)return '条件尚未完成，请先选择字段、判断方式和值';return describeNode(filters)});const workflowActiveStep=computed(()=>workflow.published?4:workflow.taskStatus==='SUCCEEDED'&&workflow.resultsLoaded?3:workflow.compiled?2:1);const isTerminalTask=computed(()=>['SUCCEEDED','SUCCESS','FAILED','CANCELED','CANCELLED','PARTIAL_SUCCEEDED'].includes(String(workflow.taskStatus).toUpperCase()));const canPublish=computed(()=>workflow.compiled&&['SUCCEEDED','SUCCESS'].includes(String(workflow.taskStatus).toUpperCase())&&workflow.resultsLoaded&&['PASSED','PASS',''].includes(String(workflow.qualityStatus||'').toUpperCase())&&!workflow.published&&!loading.publish);const trialButtonLabel=computed(()=>{if(loading.trial||loading.result)return '正在试算并读取结果';if(workflow.resultsLoaded)return '重新试算并查看结果';if(workflow.taskId&&!isTerminalTask.value)return '继续查询并查看结果';return '试算并查看结果'});
const currentTimeFieldCode=computed(()=>tables.value.find(item=>item.code===dslForm.tableCode)?.defaultTimeSemanticFieldCode||'')
const currentTimeFieldLabel=computed(()=>{if(!dslForm.tableCode)return '选择语义表后显示';if(!currentTimeFieldCode.value)return '当前语义表未配置';const field=fieldByCode(fields.value,currentTimeFieldCode.value);return field?`${field.label}（${field.code}）`:`${currentTimeFieldCode.value}（待加载字段说明）`})
const supportedFilterFields=computed(()=>filterFields.value.filter(field=>field.kind==='DATETIME'))
const filterPreview=computed(()=>{ruleVersion.value;if(scopeMode.value==='ALL')return '统计当前语义表中的全部记录（DSL filters = TRUE）';if(!filters.children?.length)return '请添加一条日期字段条件';const errors=validateFilterNode(filters);return errors[0]||describeNode(filters)})
const caliberDescription=computed(()=>{const aggregation=aggregationOptions.find(item=>item.value===dslForm.aggregation)?.label||'未选择统计方式';const selectedField=fieldByCode(fields.value,dslForm.fieldCode);const target=dslForm.aggregation==='COUNT'?(selectedField?`${selectedField.label}的非空值`:'全部记录'):selectedField?.label||'未选择统计字段';const scope=scopeMode.value==='ALL'?'全部记录':filterPreview.value;return `从“${currentDomainName.value}”的“${currentTableName.value||'未选择语义表'}”中，按${aggregation}统计${target}；业务范围：${scope}；结果粒度：${grainDescription.value}。`})
onMounted(async()=>{await loadDomains();if(template.templateId)await loadParameterSchema();if(!isCreate.value)await loadExisting()})
async function loadExisting(){try{const factor=await fetchFactor(route.params.id);basicForm.code=factor.code??factor.factorCode??basicForm.code;basicForm.name=factor.name??factor.factorName??'';basicForm.description=factor.description??'';basicForm.category=factor.category??'';resourceVersion.value=Number(factor.resourceVersion??factor.version??0);const version=await loadLatestFactorVersion(factor);const dsl=version?.dsl??factor.dsl??factor.factorDsl??factor.latestVersion?.dsl??{};dslForm.domainCode=dsl.primaryDomain?.domainCode??dsl.domainCode??dslForm.domainCode;dslForm.tableCode=dsl.primaryDomain?.semanticTableCode??'';dslForm.aggregation=dsl.aggregation?.function??'COUNT';dslForm.fieldCode=dsl.aggregation?.fieldCode??'';dslForm.groupBy=(dsl.groupBy||[]).map(x=>x.fieldCode||x);Object.keys(filters).forEach(key=>delete filters[key]);Object.assign(filters,toEditableFilterRoot(dsl.filters));scopeMode.value=(dsl.filters?.nodeType==='TRUE'||(dsl.filters?.nodeType==='AND'&&!dsl.filters?.children?.length))?'ALL':'FILTERED';hydrateWorkflow(factor,version);await loadTables(true)}catch(e){ElMessage.warning(e?.message||'因子详情读取失败')}}
async function loadLatestFactorVersion(factor){const factorId=factor.id??factor.factorId??route.params.id;const versions=await fetchFactorVersionsByFactor(factorId);const rows=normalize(versions);const preferred=rows.find(item=>item.id===factor.draftVersionId||item.versionId===factor.draftVersionId)||rows.find(item=>(item.status||item.publicationStatus)==='DRAFT')||rows.sort((a,b)=>Number(b.versionNo||0)-Number(a.versionNo||0))[0];const versionId=preferred?.id??preferred?.versionId;return versionId?fetchFactorVersion(versionId):null}
async function loadDomains(){loading.domains=true;try{domains.value=adaptDataDomainList(await fetchDataDomains()).filter(x=>x.code&&(x.status||'PUBLISHED')==='PUBLISHED');if(isCreate.value){dslForm.domainCode='';tables.value=[]}else if(dslForm.domainCode)await loadTables(true)}catch(e){ElMessage.warning(e?.message||'数据域读取失败')}finally{loading.domains=false}}
async function handleDomainChange(){metadataRequestVersion.value++;dslForm.tableCode='';dslForm.fieldCode='';dslForm.groupBy=[];fields.value=[];filters.children.splice(0);await loadTables(false)}
async function handleTableChange(){metadataRequestVersion.value++;dslForm.fieldCode='';dslForm.groupBy=[];fields.value=[];filters.children.splice(0);await loadFields()}
async function loadTables(preserveTable=false){const d=domains.value.find(x=>x.code===dslForm.domainCode);if(!d?.id){tables.value=[];return}const requestedTable=preserveTable?dslForm.tableCode:'';tables.value=adaptSemanticTableList(await fetchSemanticTables(d.id)).filter(x=>x.code&&(x.status||'PUBLISHED')==='PUBLISHED');dslForm.tableCode=requestedTable&&tables.value.some(x=>x.code===requestedTable)?requestedTable:'';if(dslForm.tableCode)await loadFields()}
async function loadFields(){const requestId=++metadataRequestVersion.value;const d=domains.value.find(x=>x.code===dslForm.domainCode);if(!d?.id||!dslForm.tableCode){fields.value=[];return}try{const data=await fetchSemanticTableFields(d.id,dslForm.tableCode);if(requestId!==metadataRequestVersion.value)return;fields.value=adaptSemanticFieldList(data).map(normalizeSemanticField).filter(x=>x.code);pruneFieldReferences()}catch(e){if(requestId===metadataRequestVersion.value)ElMessage.warning(e?.message||'语义字段读取失败')}}
function pruneFieldReferences(){const valid=new Set(fields.value.map(x=>x.code));if(!valid.has(dslForm.fieldCode))dslForm.fieldCode='';dslForm.groupBy=dslForm.groupBy.filter(code=>valid.has(code));pruneFilterNode(filters,valid)}
function pruneFilterNode(node,valid){if(!node)return;if(node.nodeType==='PREDICATE'&&!valid.has(node.fieldCode)){node.fieldCode='';node.value='';node.operator='EQ'};(node.children||[]).forEach(child=>pruneFilterNode(child,valid));if(node.child)pruneFilterNode(node.child,valid)}
async function loadParameterSchema(){if(!template.templateId)return;loading.template=true;try{const data=await fetchFactorTemplateParameterSchema(template.templateId);parameters.value=normalize(data?.parameters??data);parameters.value.forEach(x=>{if(!(x.code in parameterValues))parameterValues[x.code]=x.defaultValue??''})}catch(e){ElMessage.error(e?.message||'模板参数读取失败')}finally{loading.template=false}}
function selectAggregation(value){dslForm.aggregation=value;if(value!=='COUNT'&&!aggregatableFields.value.some(field=>field.code===dslForm.fieldCode))dslForm.fieldCode=''}
function buildDsl(){return buildFactorDsl({domainCode:dslForm.domainCode,semanticTableCode:dslForm.tableCode,aggregation:dslForm.aggregation,fieldCode:dslForm.fieldCode,groupBy:dslForm.groupBy,filters:scopeMode.value==='ALL'?{nodeType:'TRUE'}:filters})}
function hasPeriodParameter(node){return !!node&&(node.nodeType==='PREDICATE'&&node.parameter==='period'||(node.children||[]).some(hasPeriodParameter)||hasPeriodParameter(node.child))}
async function saveFactor(){if(!(await basicFormRef.value?.validate().catch(()=>false)))return;if(!dslForm.domainCode||!dslForm.tableCode)return ElMessage.warning('请选择数据域和语义表');const valid=new Set(fields.value.map(x=>x.code));if((dslForm.fieldCode&&!valid.has(dslForm.fieldCode))||dslForm.groupBy.some(x=>!valid.has(x)))return ElMessage.warning('统计字段和分组维度必须来自当前语义表');const errors=scopeMode.value==='FILTERED'?validateFilterNode(filters):[];if(errors.length)return ElMessage.warning(errors[0]);if(scopeMode.value==='FILTERED'&&hasPeriodParameter(filters)&&!tables.value.find(x=>x.code===dslForm.tableCode)?.defaultTimeSemanticFieldCode)return ElMessage.warning('当前语义表未配置默认时间字段，无法执行统计周期试算');if(dslForm.aggregation!=='COUNT'&&!dslForm.fieldCode)return ElMessage.warning('请选择统计字段');loading.save=true;try{const wasCreate=isCreate.value;const payload={name:basicForm.name,description:basicForm.description,category:basicForm.category||null,dsl:buildDsl(),resourceVersion:resourceVersion.value};const result=wasCreate?(template.versionId?await instantiateFactorTemplateVersion(template.versionId,{parameters:parameterValues,overrides:{code:basicForm.code,name:basicForm.name,description:basicForm.description}}):await createFactor({code:basicForm.code,name:basicForm.name,description:basicForm.description,category:basicForm.category||undefined,dsl:buildDsl()})):await updateFactor(route.params.id,payload);resourceVersion.value=Number(result?.resourceVersion??result?.version??resourceVersion.value);workflow.factorId=toOpaqueId(result?.id??result?.factorId??workflow.factorId??route.params.id);workflow.versionId=toOpaqueId(result?.draftVersionId??result?.versionId??workflow.versionId);workflow.status=result?.status||workflow.status||'DRAFT';workflow.published=workflow.status==='PUBLISHED';resetWorkflowAfterDefinitionChange();if(wasCreate&&workflow.factorId)await router.replace(`/factor/edit/${encodeURIComponent(workflow.factorId)}`);workflow.message=`因子草稿已保存，版本 ID：${workflow.versionId}。请继续执行编译校验。`;workflow.messageType='success';ElMessage.success(wasCreate?'因子草稿已保存，请继续编译校验':'因子修改已保存，请重新编译校验')}catch(e){ElMessage.error(e?.message||'因子保存失败')}finally{loading.save=false}}
function hydrateWorkflow(factor,version){workflow.factorId=toOpaqueId(factor?.id??factor?.factorId??route.params.id);workflow.versionId=toOpaqueId(version?.id??version?.versionId??factor?.draftVersionId??factor?.currentPublishedVersionId);workflow.status=version?.publicationStatus??version?.status??factor?.status??'DRAFT';workflow.artifactId=toOpaqueId(version?.currentArtifactId??version?.artifactId);workflow.compiled=Boolean(workflow.artifactId)||['VALID','VALIDATED'].includes(String(version?.compileStatus||'').toUpperCase());workflow.published=workflow.status==='PUBLISHED'}
function resetWorkflowAfterDefinitionChange(){workflow.artifactId='';workflow.compiled=false;workflow.taskId='';workflow.batchId='';workflow.taskStatus='';workflow.qualityStatus='';workflow.resultsLoaded=false;trialRows.value=[];workflow.published=false}
async function compileCurrentVersion(){if(!workflow.versionId||loading.compile)return;loading.compile=true;try{const result=await compileFactorVersion(workflow.versionId,{});workflow.artifactId=toOpaqueId(result?.artifactId??result?.id??result?.compileArtifactId);const status=String(result?.status??result?.compileStatus??'VALID').toUpperCase();workflow.compiled=['VALID','VALIDATED','SUCCEEDED','SUCCESS'].includes(status);workflow.status=workflow.compiled?'VALIDATED':workflow.status;workflow.message=workflow.compiled?`编译校验通过${workflow.artifactId?'，产物 ID：'+workflow.artifactId:''}`:`编译已完成，状态：${status}`;workflow.messageType=workflow.compiled?'success':'warning';if(workflow.compiled)ElMessage.success('计算口径校验通过');else ElMessage.warning(workflow.message)}catch(e){workflow.compiled=false;workflow.message=e?.message||'因子编译失败';workflow.messageType='error';ElMessage.error(workflow.message)}finally{loading.compile=false}}
async function trialCurrentVersion(){if(!workflow.compiled||loading.trial||loading.result)return;if(workflow.taskId&&!isTerminalTask.value)return refreshTrialStatus();if(workflow.taskStatus==='SUCCEEDED'&&workflow.batchId&&!workflow.resultsLoaded)return loadTrialResults();if(!Array.isArray(trialPeriod.value)||trialPeriod.value.length!==2)return ElMessage.warning('请选择完整的试算时间范围');loading.trial=true;trialRows.value=[];workflow.resultsLoaded=false;try{const key=`factor-trial-${workflow.versionId}-${Date.now()}`;const accepted=await trialFactorVersion(workflow.versionId,{periodStart:trialPeriod.value[0],periodEnd:trialPeriod.value[1]},key);workflow.taskId=toOpaqueId(accepted?.taskId??accepted?.asyncTaskId);workflow.batchId=toOpaqueId(accepted?.batchId);workflow.taskStatus=String(accepted?.status??'QUEUED').toUpperCase();workflow.message=`试算任务已提交，批次 ID：${workflow.batchId||'-'}。正在等待后端完成。`;workflow.messageType='info';ElMessage.success('试算任务已提交');if(workflow.taskId)await pollTrialTask();if(['SUCCEEDED','SUCCESS'].includes(workflow.taskStatus))await loadTrialResults()}catch(e){workflow.message=e?.message||'因子试算提交失败';workflow.messageType='error';ElMessage.error(workflow.message)}finally{loading.trial=false}}
async function pollTrialTask(){for(let i=0;i<15;i+=1){const task=await fetchAsyncTask(workflow.taskId);workflow.taskStatus=String(task?.status??workflow.taskStatus).toUpperCase();workflow.batchId=toOpaqueId(task?.batchId??workflow.batchId);if(isTerminalTask.value)break;await wait(2000)}if(['SUCCEEDED','SUCCESS'].includes(workflow.taskStatus)){workflow.message='试算任务已完成，正在读取结果。';workflow.messageType='success'}else if(isTerminalTask.value){workflow.message=`试算任务结束，状态：${workflow.taskStatus}`;workflow.messageType='warning'}else{workflow.message='试算仍在处理中，可点击“继续查询并查看结果”。';workflow.messageType='info'}}
async function refreshTrialStatus(){if(!workflow.taskId||loading.status)return;loading.status=true;try{const task=await fetchAsyncTask(workflow.taskId);workflow.taskStatus=String(task?.status??workflow.taskStatus).toUpperCase();workflow.batchId=toOpaqueId(task?.batchId??workflow.batchId);workflow.message=`试算任务状态：${workflow.taskStatus}`;workflow.messageType=['SUCCEEDED','SUCCESS'].includes(workflow.taskStatus)?'success':isTerminalTask.value?'warning':'info';if(['SUCCEEDED','SUCCESS'].includes(workflow.taskStatus))await loadTrialResults()}catch(e){ElMessage.error(e?.message||'任务状态查询失败')}finally{loading.status=false}}
async function loadTrialResults(){if(!workflow.versionId||!workflow.batchId||loading.result)return;loading.result=true;try{const result=await fetchFactorTrialResults(workflow.versionId,workflow.batchId,1,100);const payload=result?.data??result;const records=payload?.results?.records??payload?.records??payload?.result?.records??[];const scalar=payload?.valueDecimal??payload?.result?.valueDecimal??payload?.resultValue??payload?.value;trialRows.value=records.length?normalize(records):(scalar!==undefined&&scalar!==null?[{valueDecimal:scalar,displayValue:payload?.displayValue??payload?.result?.displayValue??scalar,qualityStatus:payload?.qualityStatus??payload?.result?.qualityStatus}]:[]);workflow.resultsLoaded=String(payload?.batchStatus??payload?.status??'SUCCEEDED').toUpperCase()==='SUCCEEDED';workflow.qualityStatus=payload?.qualityStatus??payload?.result?.qualityStatus??trialRows.value[0]?.qualityStatus??'';if(!workflow.taskStatus)workflow.taskStatus='SUCCEEDED';if(!workflow.resultsLoaded)throw new Error(`试算结果状态为 ${payload?.batchStatus??payload?.status??'UNKNOWN'}，尚未达到成功终态`);workflow.message=trialRows.value.length?`试算结果已读取，共 ${trialRows.value.length} 条，质量状态：${workflow.qualityStatus||'未返回'}`:'试算结果已读取，本周期没有命中记录。';workflow.messageType='success';ElMessage.success('试算结果读取成功')}catch(e){workflow.resultsLoaded=false;workflow.message=e?.message||'试算结果读取失败';workflow.messageType='error';ElMessage.error(workflow.message)}finally{loading.result=false}}
async function publishCurrentVersion(){if(!canPublish.value)return;try{await ElMessageBox.confirm(`确认发布因子版本 ${workflow.versionId}？发布后该版本将供指标正式引用。`,'发布因子版本',{confirmButtonText:'确认发布',cancelButtonText:'返回检查',type:'warning'})}catch{return}loading.publish=true;try{const result=await publishFactorVersion(workflow.versionId);workflow.status=result?.status??result?.publicationStatus??'PUBLISHED';workflow.published=true;workflow.message=`因子版本 ${workflow.versionId} 已发布，可供指标引用。`;workflow.messageType='success';ElMessage.success('因子版本已发布')}catch(e){workflow.message=e?.message||'因子版本发布失败';workflow.messageType='error';ElMessage.error(workflow.message)}finally{loading.publish=false}}
function formatDimensions(row){const dimensions=row?.dimensions??row?.dimensionValues??row?.dimension??{};if(!dimensions||!Object.keys(dimensions).length)return '总体';return Object.entries(dimensions).map(([key,value])=>`${key}=${value}`).join('，')}
function resultValue(row){return row?.displayValue??row?.valueDecimal??row?.resultValue??row?.value??'-'}
function toOpaqueId(value){return value===undefined||value===null||value===''?'':String(value)}
function wait(ms){return new Promise(resolve=>setTimeout(resolve,ms))}
function toEditableFilterRoot(node){if(!node||node.nodeType==='TRUE')return{nodeType:'AND',children:[]};const normalized=withFilterId(node);return['AND','OR'].includes(normalized.nodeType)?normalized:{nodeType:'AND',children:[normalized]}}
function withFilterId(node){if(!node)return node;const result={...node,id:node.id||`filter-${Date.now()}-${Math.random()}`};if(node.children)result.children=node.children.map(withFilterId);if(node.child)result.child=withFilterId(node.child);return result}
function metadataOptionLabel(item){const name=String(item?.name||'').trim();const code=String(item?.code||'').trim();return name&&name!==code?`${name}（${code}）`:code||name||'未命名'}
function fieldOptionLabel(field){const label=metadataOptionLabel({name:field.label,code:field.code});const type=fieldTypeLabel(field.kind||field.dataType);const source=field.sourceFieldName?` · 来源：${field.sourceFieldName}`:'';const sensitive=field.sensitive?' · 敏感':'';return `${label} · ${type}${source}${sensitive}`}
function fieldTypeLabel(value){return({STRING:'文本',CODE:'编码',VALUE_SET:'值集',NUMBER:'数值',DATETIME:'日期时间'} )[String(value||'').toUpperCase()]||value||'字段'}
function describeNode(node){if(!node)return'';if(node.nodeType==='PREDICATE'){const field=fieldByCode(fields.value,node.fieldCode);const label=field?.label||'未选择字段';if(node.parameter==='period')return `${label}在统计周期内`;const value=Array.isArray(node.value)?node.value.join('至'):node.value;return `${label}${operatorLabel(node.operator)}${value||'未填写'}`}if(node.nodeType==='NOT')return `不满足（${describeNode(node.child)}）`;return (node.children||[]).map(describeNode).filter(Boolean).join(node.nodeType==='OR'?'，或':'，且')}
function operatorLabel(value){return({EQ:'等于',IN:'属于',IN_VALUE_SET:'属于值集',GTE:'晚于或等于',LTE:'早于或等于',GT:'大于',LT:'小于',BETWEEN:'在统计周期内'})[value]||value||''}function normalize(x){if(Array.isArray(x))return x;return x?.records||x?.list||x?.items||x?.data||[]}
</script>
